const D = { height:.5, energy:.55, hue:28, speed:1, density:.4, scale:1, x:.5, y:.72, style:'mirage', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;

// ---- cached gradient/heat strip, keyed on size+seed+style+hue-bucket ----
const hueBucket = Math.round(P.hue/12);
const key = width+'x'+height+'|'+P.seed+'|'+P.style+'|'+hueBucket;
if (!S.grad || S.gkey !== key) {
  const gw = 220, gh = 256;
  const g = createGraphics(gw, gh);
  g.colorMode(HSB, 360, 100, 100, 100);
  g.noStroke();
  const ramp = (t) => { // t 0(bottom/hot) .. 1(top/cool) -> [h,s,v]
    if (P.style === 'thermal') {
      if (t < .25) return [hw(P.hue+30), 20, 100];      // white-hot
      if (t < .5)  return [hw(P.hue+10), 85, 96];
      if (t < .75) return [hw(P.hue-20), 95, 70];
      return [hw(P.hue-70), 90, 34];
    }
    if (P.style === 'oil') { // iridescent oil-slick sheen
      return [hw(P.hue + t*260), 65, 55 + Math.sin(t*10)*20 + 30];
    }
    if (P.style === 'ink') { // desaturated sumi wash, dark-key
      return [hw(P.hue), 10, 20 + (1-t)*55];
    }
    if (P.style === 'scanline') { // will be overdrawn as bars; base warm
      return [hw(P.hue), 55, 30 + (1-t)*55];
    }
    // mirage default: warm desert horizon ramp
    return [hw(P.hue + (1-t)*24), 55 + (1-t)*35, 38 + (1-t)*54];
  };
  for (let y = 0; y < gh; y++) {
    const t = y/gh;
    const c = ramp(t);
    // baked horizontal seed-noise so the wobble reveals structure
    for (let x = 0; x < gw; x += 4) {
      const n = Math.sin(x*0.09 + fr(y*7)*6.2) * 0.5 + 0.5;
      g.fill(c[0], c[1], c[2]*(0.82 + n*0.18), 100);
      g.rect(x, y, 4, 1);
    }
  }
  if (P.style === 'scanline') { // punch dark gaps -> dot-matrix bars
    g.fill(0,0,0,100);
    for (let y = 0; y < gh; y += 4) g.rect(0, y, gw, 2);
  }
  S.grad = g; S.gkey = key;
}

const bandH = Math.max(0.06, Math.min(1, P.height)) * height;
const cy = P.y * height;
let top = cy - bandH*0.5;
if (top + bandH > height) top = height - bandH;
if (top < 0) top = 0;
const bandW = width * (0.6 + P.scale*0.55);
const bx = P.x*width - bandW*0.5;

const nStrips = Math.max(24, Math.min(110, Math.round(bandH / Math.max(3, u*0.006))));
const stripH = bandH / nStrips;
const gsH = S.grad.height / nStrips;

// wobble amplitude: continuous baseline + audio, breathe
const amp = u * (0.012 + P.energy*0.05) * (0.7 + K.swell*0.5 + A.bass*0.9);
const freq = 5.5 + P.density*7;
const roll = K.t*(0.9 + P.speed*1.1);   // real-time scroll — never rephases

const blend = (P.style === 'ink') ? BLEND : SCREEN;
const alpha = (P.style === 'ink') ? 55 : (P.style==='scanline'? 60 : 42 + K.intensity*22);

push();
blendMode(blend);
tint(0, 0, 100, alpha);
for (let s = 0; s < nStrips; s++) {
  const y = top + s*stripH;
  const yf = s/nStrips;
  // layered heat wobble: two waves + slow drift, all real-time
  const dx = Math.sin(yf*freq + roll)*amp
           + Math.sin(yf*freq*2.3 - roll*1.7 + 1.3)*amp*0.4
           + Math.sin(K.t*0.3 + yf*3)*amp*0.5;
  const squash = 1 + Math.sin(yf*freq*0.6 + roll*0.7)*0.04;
  image(S.grad, bx+dx, y, bandW*squash, stripH+1, 0, s*gsH, S.grad.width, gsH);
}
noTint();

// ---- rising heat wisps (density) — continuous upward travel ----
if (P.density > 0.02) {
  blendMode(SCREEN);
  noStroke();
  const nW = Math.round(P.density * 22);
  for (let i = 0; i < nW; i++) {
    const wx = bx + fr(i*2+1)*bandW + Math.sin(K.t*(0.4+fr(i)*0.6)+i)*u*0.03;
    const prog = (fr(i*2+2) + K.t*(0.05 + fr(i+9)*0.06)*P.speed) % 1;
    const wy = top + bandH - prog*bandH;
    const life = Math.sin(prog*Math.PI);
    const wv = 40 + life*40 + A.rms*40;
    fill(hw(P.style==='ink'?P.hue:P.hue+16), P.style==='ink'?10:45, wv, (6 + life*16));
    ellipse(wx, wy, u*0.018*P.scale, u*0.05*P.scale*(0.6+life));
  }
}

blendMode(BLEND);
pop();
if (drawingContext) drawingContext.shadowBlur = 0;
